'use strict';

const giText=value=>String(value??'').trim();
const giHash=value=>recHashText(recStable(value));
function giState(){S.governanceInteractions??={version:1,roleBases:{},policyBases:{},inbox:{},policyTest:null};return S.governanceInteractions;}
function giActorControl(){return `<label class="gi-identity">Working as <select data-doc-actor aria-label="Working identity">${options(REC_PEOPLE.map(p=>[p.id,p.name]),recActor().id)}</select></label>`;}
function giIssues(items,title='Complete before continuing'){return typeof ui211Issues==='function'?ui211Issues(items.map(x=>typeof x==='string'?{message:x}:x),{title}):items.length?`<div class="gi-issues" role="status"><strong>${e(title)}</strong><ul>${items.map(x=>`<li>${e(x.message||x)}</li>`).join('')}</ul></div>`:'';}
function giNext(config){return typeof ui211Next==='function'?ui211Next(config):`<section class="gi-next"><div><strong>${e(config.title)}</strong><p>${e(config.description||'')}</p>${config.owner?`<small>${e(config.owner)}</small>`:''}</div><div class="row wrap">${config.primary||''}${config.secondary||''}</div></section>`;}
function giRoute(name,patch={}){const params=new URLSearchParams(current.name===name?current.params.toString():'');for(const [key,value]of Object.entries(patch)){if(value===''||value==null)params.delete(key);else params.set(key,String(value));}return name+(params.size?'?'+params.toString():'');}
function giDay(value){const day=giText(value).slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(day)&&!Number.isNaN(Date.parse(day+'T00:00:00Z'))?day:'';}
function giDue(value,closed=false){const day=giDay(value);if(!day)return {bucket:3,label:'No due date',sort:'9999-12-31',tone:'',days:null};const distance=days(day,S.asOf);return {bucket:closed?4:distance<0?0:distance===0?1:2,label:closed?'Completed':distance<0?Math.abs(distance)+'d overdue':distance===0?'Due today':distance<=7?'Due in '+distance+'d':date(day),sort:day,tone:!closed&&distance<0?'red':!closed&&distance<=7?'amber':'',days:distance};}
function giOwnerId(row){return row.ownerId||recUserId(row.owner)||'';}
function giWorkType(row){const text=String(typeof d210WorkLabel==='function'?d210WorkLabel(row.kind):row.kind||'Action');return text;}
function giWorkAction(row){if(row.status==='Completed')return 'View outcome';if(row.source==='task')return 'Review action';if(/correction|correct/i.test(row.kind+' '+row.title))return 'Correct & resubmit';if(/assignment/i.test(row.kind))return 'Assign respondent';if(/response$/i.test(row.kind))return 'Complete response';if(/document request/i.test(row.kind))return 'Supply document';if(/owner confirmation/i.test(row.kind))return 'Confirm scope';if(/conclusion/i.test(row.kind))return 'Evaluate requirement';return /review|approval|decision/i.test(row.kind)?'Review submission':'Open next step';}
function giWorkRows(config={},rows=workItems()){
 const owner=config.owner||'me',lane=config.lane||'open',kind=config.kind||'',search=giText(config.search).toLowerCase();
 return rows.filter(row=>{if(owner!=='all'&&giOwnerId(row)!==(owner==='me'?recActor().id:owner))return false;if(kind&&row.kind!==kind)return false;if(search&&![row.title,row.owner,row.kind,row.ref,row.id].join(' ').toLowerCase().includes(search))return false;const open=row.status!=='Completed',due=giDue(row.due);return lane==='all'||lane==='completed'?!open||lane==='all':lane==='overdue'?open&&due.days!==null&&due.days<0:lane==='soon'?open&&due.days!==null&&due.days>=0&&due.days<=7:lane==='reviews'?open&&uxIsReviewItem(row):lane==='corrections'?open&&/correction|correct/i.test(row.kind+' '+row.title):open;}).sort((a,b)=>{const ac=a.status==='Completed',bc=b.status==='Completed';return Number(ac)-Number(bc)||giDue(a.due,ac).sort.localeCompare(giDue(b.due,bc).sort)||Number(!/correction/i.test(a.kind))-Number(!/correction/i.test(b.kind))||a.title.localeCompare(b.title)||a.id.localeCompare(b.id);});
}
function giWorkConfig(){const p=current.params,legacy=p.get('tab');return {owner:p.get('owner')||'me',lane:p.get('lane')||(legacy==='review'?'reviews':legacy==='all'?'all':'open'),kind:p.get('kind')||'',search:p.get('q')||''};}
/* Bounded work-queue return context; no arbitrary return URL or access changes. */
function giWorkContext(config){
 const owner=['me','all',...REC_PEOPLE.map(person=>person.id)].includes(config.owner)?config.owner:'me';
 const lane=['open','overdue','soon','reviews','corrections','completed','all'].includes(config.lane)?config.lane:'open';
 const kind=String(config.kind||'').slice(0,120),search=String(config.search||'').slice(0,200);
 return {owner,lane,kind,search};
}
function giWorkItemRoute(id,config=giWorkConfig()){
 const context=giWorkContext(config),params=new URLSearchParams({id});
 for(const [key,value]of Object.entries(context))if(value)params.set('w'+key,value);
 return 'work-item?'+params.toString();
}
function giWorkBackRoute(){
 const params=current.params;if(!['owner','lane','kind','search'].some(key=>params.has('w'+key)))return 'work';
 const context=giWorkContext(Object.fromEntries(['owner','lane','kind','search'].map(key=>[key,params.get('w'+key)]))),back=new URLSearchParams({owner:context.owner,lane:context.lane});
 if(context.kind)back.set('kind',context.kind);if(context.search)back.set('q',context.search);
 return 'work?'+back.toString();
}
function giWorkView(){const config=giWorkConfig(),all=workItems(),rows=giWorkRows(config,all),lanes=[['open','Open'],['overdue','Overdue'],['soon','Due in 7 days'],['reviews','Reviews'],['corrections','Corrections'],['completed','Completed'],['all','All']];return header('Work & approvals','Find the accountable action, its deadline and the exact source to continue.',btn(icon('plus')+' Create action','new-action','','primary'),'Work')+`<div class="gi-queue-context">${giActorControl()}<p>Dates are evaluated against ${date(S.asOf)}. Completing an action leaves source reviews and conclusions separate.</p></div><nav class="gi-lanes" aria-label="Work queue views">${lanes.map(([key,title])=>link(title+` <span>${giWorkRows({...config,lane:key,search:'',kind:''},all).length}</span>`,giRoute('work',{lane:key,tab:null}),config.lane===key?'active':'')).join('')}</nav><form data-gi-filter="work" class="gi-filters">${select('owner','Accountability',[['me','Assigned to me'],['all','Everyone in this scope'],...REC_PEOPLE.map(p=>[p.id,p.name])],config.owner)}${select('kind','Work type',[['','All work types'],...[...new Set(all.map(row=>row.kind))].sort().map(kind=>[kind,typeof d210WorkLabel==='function'?d210WorkLabel(kind):kind])],config.kind)}${input('q','Search work',config.search,'search','placeholder="Title, owner, source or reference"')}<input type="hidden" name="lane" value="${e(config.lane)}"><button class="btn small" type="submit">Apply filters</button>${link('Clear','work?owner='+encodeURIComponent(config.owner),'quiet small')}</form><div class="gi-result-count" role="status">${rows.length} matching ${rows.length===1?'item':'items'} · oldest due dates first</div>`+panel('Accountable work','Every row opens its current source. Source decisions are never completed from a queue.',rows.length?table(['Work / next step','Accountable owner','Due','State',''],rows.map(row=>{const due=giDue(row.due,row.status==='Completed');return {cells:[`<strong>${e(row.title)}</strong><small>${e(giWorkType(row))} · ${e(row.ref||row.id)}</small>`,e(row.owner||'Unassigned'),`${pill(due.label,due.tone)}${giDay(row.due)?'<small>'+date(giDay(row.due))+'</small>':''}`,pill(row.status),link(giWorkAction(row),row.source==='task'?giWorkItemRoute(row.id,config):row.route,'small')]};})):empty('No work matches this view',config.owner==='me'?'Change the work filter or inspect the scoped team queue.':'Change the filters or select another organizational location.',link('View scoped team work','work?owner=all&lane=open','small')));}
function giWorkItemView(){const item=workItems().find(x=>x.id===current.params.get('id'));if(!item)return uxUnavailable('This action is unavailable in the selected location.',giWorkBackRoute());if(item.source!=='task')return header(e(item.title),'Continue in the source workflow.',link(giWorkAction(item),item.route,'primary'));
 const task=S.tasks.find(x=>x.id===item.id),source=task&&flTaskSource(task),record=source&&recRead(source.type,source.id),route=record?task.route||recUrl(source.type,source.id):'',due=giDue(item.due,item.status==='Completed');return header(e(item.title),e(giWorkType(item))+' · '+e(item.id),link('Back to work',giWorkBackRoute()),'Action')+giActorControl()+giNext({title:item.status==='Completed'?'Recorded outcome':giWorkAction(item),description:item.outcome||item.description||'Review the required outcome and record what was completed.',owner:item.owner,due:item.due,state:item.status,primary:btn(item.status==='Completed'?'Inspect outcome / reopen':'Record completion','task-detail',`data-id="${e(item.id)}"`,'primary'),secondary:route?link('Open source',route,'small'):''})+panel('Action details','The action and its source retain their own decision history.',`<dl class="gi-facts"><div><dt>Owner</dt><dd>${e(item.owner||'Unassigned')}</dd></div><div><dt>Deadline</dt><dd>${date(item.due)} ${pill(due.label,due.tone)}</dd></div><div><dt>State</dt><dd>${e(item.status)}</dd></div><div><dt>Source</dt><dd>${record?e(recName(source.type,record)):e(item.ref||'Standalone action')}</dd></div></dl>${item.status==='Completed'?`<div class="pad"><h3>Completion outcome</h3><p>${e(item.note||'No outcome recorded')}</p><small>${e(item.completedBy||item.owner)} · ${date(item.completed)}</small></div>`:''}${!record&&item.ref?giIssues(['The referenced source is unavailable. Restore its context before recording completion.'],'Source needs attention'):''}`);}
workView=giWorkView;

/* Inbox triage preserves recipient receipts and all exact-source resolvers. */
function giInboxPrefs(){return giState().inbox[nActor()]??={sort:'priority',due:'all'};}
function giNotificationPriority(event){const due=giDue(event.due),resolved=nResolved(event),active=event.actionable&&!resolved;return [resolved?3:active?0:2,active&&due.days!==null&&due.days<0?0:event.severity==='Critical'?1:event.severity==='High'?2:active&&due.days!==null&&due.days<=7?3:4,due.sort];}
const giPriorNotificationFilter=nFiltered;
nFiltered=function(){const config=giInboxPrefs();return giPriorNotificationFilter().filter(event=>{if(config.due==='all')return true;const due=giDue(event.due);return event.actionable&&!nResolved(event)&&due.days!==null&&(config.due==='overdue'?due.days<0:due.days>=0&&due.days<=7);}).sort((a,b)=>{if(config.sort==='newest')return String(b.createdAt).localeCompare(String(a.createdAt));const ap=giNotificationPriority(a),bp=giNotificationPriority(b);return ap[0]-bp[0]||ap[1]-bp[1]||ap[2].localeCompare(bp[2])||String(b.createdAt).localeCompare(String(a.createdAt))||a.id.localeCompare(b.id);});};
function giNotificationAction(event){if(event.type==='mention')return 'Open discussion';if(nResolved(event))return 'View source';if(event.sourceType==='task')return 'Review action';if(event.sourceState==='Changes requested'||event.assessmentEvent==='return')return 'Correct submission';if(event.type==='approval')return 'Review submission';if(event.sourceWorkflow==='vendor-onboarding-document')return 'Supply document';return event.type==='document'?'Review document':'Open next step';}
function giOpenNotificationSource(id){const event=nEvent(id);requireValue(nSourceAvailable(event),'The exact notification source is unavailable. Open its history for context.');if(event.type==='mention'){go('notification?id='+encodeURIComponent(event.id));return;}if(event.sourceType==='task'){const task=nRecordFor(event);requireValue(workItems().some(row=>row.id===task.id),'The action is outside the current work queue.');go('work-item?id='+encodeURIComponent(task.id));return;}const route=nSourceRoute(event);requireValue(route,'The source route is unavailable.');go(route);}
const giPriorNotificationRow=nRow;
nRow=function(event){const due=giDue(event.due,nResolved(event)),html=giPriorNotificationRow(event),action=nSourceAvailable(event)?btn(giNotificationAction(event),'gi-inbox-source',`data-id="${e(event.id)}"`,'small'):'<span class="gi-unavailable">Source unavailable</span>';return html.replace('<div class="n-row-actions">',`<div class="n-row-actions gi-notification-actions">${event.due?`<span class="gi-due ${due.tone}" title="${e(giDay(event.due))}">${e(due.label)}</span>`:''}${action}`);};
const giPriorInboxView=inboxView;
inboxView=function(){const prefs=giInboxPrefs(),controls=`<div class="gi-inbox-order"><label>Order <select data-gi-inbox="sort">${options([['priority','Action priority & due date'],['newest','Newest first']],prefs.sort)}</select></label><label>Deadline <select data-gi-inbox="due">${options([['all','All dates'],['overdue','Overdue action'],['soon','Action due in 7 days']],prefs.due)}</select></label><small>Read and acknowledged items can still need action.</small></div>`;return giPriorInboxView().replace('<div id="n-bulk"',controls+'<div id="n-bulk"');};
const giPriorInboxClear=actions['n-clear-filters'];actions['n-clear-filters']=()=>{Object.assign(giInboxPrefs(),{sort:'priority',due:'all'});save();giPriorInboxClear();};
const giPriorInboxRefinements=nRefinements;
nRefinements=function(){const filters=giPriorInboxRefinements(),due=giInboxPrefs().due;if(due!=='all')filters.push(['Deadline',due==='overdue'?'Overdue action':'Action due in 7 days']);return filters;};
const giPriorInboxReset=actions['n-reset-refinements'];
actions['n-reset-refinements']=()=>{giInboxPrefs().due='all';save();giPriorInboxReset();};
const giPriorFollowUp=nFollowUp;
nFollowUp=function(event){const existing=event.followUpId&&S.tasks.find(t=>t.id===event.followUpId);if(existing){requireValue(workItems().some(x=>x.id===existing.id),'The existing follow-up is unavailable in the current location.');go('work-item?id='+encodeURIComponent(existing.id));return;}requireValue(nSourceAvailable(event),'Restore the exact source before creating a follow-up.');giPriorFollowUp(event);const commit=modalSave;modalSave=form=>{requireValue(!event.followUpId||!S.tasks.some(x=>x.id===event.followUpId),'A follow-up was already created. Open the existing action.');requireValue(!nResolved(event)&&nSourceAvailable(event),'The source changed or no longer needs this action.');const result=commit(form);if(event.followUpId)go('work-item?id='+encodeURIComponent(event.followUpId));return result;};};
const giPriorNotificationDetail=nDetailView;
nDetailView=function(){const html=giPriorNotificationDetail(),event=S.notificationsV28.events.find(x=>x.id===current.params.get('id'));return event?.followUpId&&nCanSee(event)?html.replace('href="#/work"','href="#/work-item?id='+encodeURIComponent(event.followUpId)+'"').replace('Open work queue','Open follow-up action'):html;};

/* Access previews run the same decision function against a temporary clone. */
function giWithAccess(state,fn){const original=S.accessControl;try{S.accessControl=state;return clone(fn());}finally{S.accessControl=original;}}
function giAccessHash(){return giHash({roles:gvState().roles,assignments:gvState().assignments,directRules:gvState().directRules});}
function giRequireAccess(scope=''){requireValue(!S.scopeInvalid&&gvDecision(recActor().id,'access.manage',scope).allowed,'Switch to an active access administrator for this location.');}
function giPermissionLabel(permission){const [module,action]=permission.split('.');return (GV_MODULES.find(x=>x[0]===module)?.[1]||module)+' · '+(GV_ACTIONS.find(x=>x[0]===action)?.[1]||action);}
function giAccessComparison(next,people,scopes,on=S.asOf,permissions=GV_MODULES.flatMap(([module])=>GV_ACTIONS.map(([action])=>module+'.'+action))){const before=[],after=[];for(const userId of [...new Set(people)])for(const scopeId of [...new Set(scopes)])for(const permission of permissions)before.push({userId,scopeId,permission,...gvDecision(userId,permission,scopeId,on)});giWithAccess(next,()=>{for(const row of before)after.push(gvDecision(row.userId,row.permission,row.scopeId,on));return null;});return before.flatMap((row,index)=>row.allowed!==after[index].allowed?[{userId:row.userId,person:gvPerson(row.userId)?.name,scopeId:row.scopeId,scope:gvScope(row.scopeId),permission:row.permission,before:row.allowed,after:after[index].allowed,reason:after[index].reason}]:[]);}
function giImpactTable(rows){if(!rows.length)return `<p class="gi-no-change">No effective allow/deny result changes for the evaluated people, locations and date. Existing explicit denies remain effective.</p>`;const groups=new Map();for(const row of rows){const key=[row.userId,row.permission,row.before,row.after,row.reason].join('|');if(!groups.has(key))groups.set(key,{...row,locations:[]});groups.get(key).locations.push(row.scope);}return table(['Person / action','Effective change','Locations / reason'],[...groups.values()].map(row=>({cells:[`<strong>${e(row.person)}</strong><small>${e(giPermissionLabel(row.permission))}</small>`,`${pill(row.before?'Allowed':'Denied')} → ${pill(row.after?'Allowed':'Denied',row.after?'green':'amber')}`,`<details><summary>${row.locations.length} location${row.locations.length===1?'':'s'}</summary>${row.locations.map(e).join('<br>')}</details><small>${e(row.reason)}</small>`]})));}
const giPriorRoleDraft=gvDraftRole;
gvDraftRole=function(id){const fresh=gvState().draftRole?.sourceId!==id,draft=giPriorRoleDraft(id);if(draft&&(fresh||!giState().roleBases[id]))giState().roleBases[id]=giHash(gvRole(id));return draft;};
const giPriorNewRole=gvNewRole;
gvNewRole=function(...args){giPriorNewRole(...args);delete giState().roleBases.new;giState().rolePreview=null;save();};
function giRolePreview(){const draft=gvState().draftRole;requireValue(draft&&!draft.system,'Choose an editable role draft.');const original=draft.newRole?null:gvRole(draft.sourceId),base=giState().roleBases[draft.sourceId];if(original&&base)requireValue(giHash(original)===base,'This role changed after editing began. Reopen the current role before applying a new change.');const next=clone(gvState()),role={...clone(draft),id:draft.newRole?'GI-PREVIEW-ROLE':draft.sourceId},at=next.roles.findIndex(x=>x.id===role.id);if(at<0)next.roles.push(role);else next.roles[at]=role;const assignments=next.assignments.filter(a=>a.roleId===role.id&&a.status==='Active'&&(!a.ends||a.ends>=S.asOf)),people=assignments.map(a=>a.userId),scopes=['',...ORG.map(n=>n.id)].filter(scope=>assignments.some(a=>gvCovers(a.scopeId,scope))),changes=[];for(const [key,label]of [['name','Name'],['description','Purpose'],['status','Status'],['scopeRoot','Maximum scope'],['descendants','Include child locations'],['reviewEvery','Review interval (days)']])if(recStable(original?.[key]??'')!==recStable(draft[key]??''))changes.push({label,before:key==='scopeRoot'?gvScope(original?.[key]||''):String(original?.[key]??'—'),after:key==='scopeRoot'?gvScope(draft[key]):String(draft[key])});for(const key of GV_MODULES.flatMap(([m])=>GV_ACTIONS.map(([a])=>m+'.'+a)))if((original?.permissions[key]||'unset')!==(draft.permissions[key]||'unset'))changes.push({label:giPermissionLabel(key),before:original?.permissions[key]||'unset',after:draft.permissions[key]||'unset'});const conflicts=gvChecks(draft);for(const a of assignments){if(!gvCovers(role.scopeRoot,a.scopeId,role.descendants))conflicts.push(gvPerson(a.userId).name+' has an assignment outside the proposed maximum scope.');conflicts.push(...gvConflictFor(a,next.roles,next.assignments));}return {draftHash:giHash(draft),accessHash:giAccessHash(),changes,assignments:clone(assignments),impact:giAccessComparison(next,people,scopes),conflicts:[...new Set(conflicts)],evaluatedAt:S.asOf};}
function giRoleReviewView(){let preview;try{preview=giRolePreview();}catch(error){return header('Role change unavailable',e(error.message),link('Roles & permissions','roles'));}const draft=gvState().draftRole;giState().rolePreview={draftHash:preview.draftHash,accessHash:preview.accessHash};return header('Review role changes',e(draft.name)+' · '+preview.changes.length+' changes',link('Continue editing','role-detail?id='+draft.sourceId),'Access governance')+giActorControl()+giIssues(preview.conflicts,'Resolve before applying')+panel('Before → after','The role definition is unchanged until Apply reviewed change succeeds.',preview.changes.length?table(['Setting / permission','Current','Proposed'],preview.changes.map(change=>({cells:[e(change.label),e(change.before),e(change.after)]}))):empty('No role changes','Return to the role to make a specific change.'))+panel('Effective access impact',`Evaluated at ${date(preview.evaluatedAt)} for ${new Set(preview.assignments.map(a=>a.userId)).size} assigned people across their covered locations. Future assignments are listed separately below.`,giImpactTable(preview.impact))+(preview.assignments.length?panel('Assignments affected','Active and scheduled assignments keep their scope and expiry.',gvAssignmentsTable(preview.assignments,false)):'')+`<section class="panel pad"><h2>Change reason</h2><p>${e(draft.reason||'Return to editing and record the business reason.')}</p><div class="row wrap">${link('Continue editing','role-detail?id='+draft.sourceId,'small')}${btn('Apply reviewed change','gi-apply-role',preview.conflicts.length||!preview.changes.length?'disabled':'','primary')}</div><div id="gi-role-error" class="form-error" role="alert"></div></section>`;}
const giPriorSaveRole=gvSaveRole;
gvSaveRole=function(){giRequireAccess();const draft=gvState().draftRole;if(draft&&!draft.newRole&&giState().roleBases[draft.sourceId])requireValue(giHash(gvRole(draft.sourceId))===giState().roleBases[draft.sourceId],'The source role changed after editing began. Reopen its current definition.');const id=draft?.sourceId;giPriorSaveRole();if(id)delete giState().roleBases[id];giState().rolePreview=null;save();};
function giApplyRole(){const pending=giState().rolePreview,draft=gvState().draftRole;requireValue(pending&&pending.draftHash===giHash(draft)&&pending.accessHash===giAccessHash(),'The draft or affected access changed. Review the comparison again.');gvSaveRole();}
const giPriorRoleDetail=gvRoleDetail;

function giDefinition(value){if(!value)return null;const out=clone(value);delete out.sourceId;delete out.newRole;delete out.reason;return out;}
function giDraftDirty(kind){const d=kind==='role'?gvState().draftRole:gvState().draftPolicy;if(!d)return false;if(d.sourceId==='new'||giText(d.reason))return true;const original=kind==='role'?gvRole(d.sourceId):gvState().policies.find(p=>p.id===d.sourceId);return giHash(giDefinition(d))!==giHash(original);}
