const giSavedRoleDraft=gvDraftRole;
gvDraftRole=function(id){const draft=gvState().draftRole;if(draft&&draft.sourceId!==id&&giDraftDirty('role'))return draft;return giSavedRoleDraft(id);};
const giSavedNewRole=gvNewRole;
