gvRoleDetail=function(){if(gvState().draftRole&&gvState().draftRole.sourceId!==current.params.get('id')&&giDraftDirty('role'))return giDraftRecovery('role',current.params.get('id'));const html=giPriorRoleDetail();return html.replace(/>Save role<\/button>/g,'>Review changes</button>').replace('<nav class="gv-nav"',`<div class="gi-working">${giActorControl()}<small>Review the effective access change before applying it.</small></div><nav class="gv-nav"`);};
