function giAccessProposal(kind,id,input){const next=clone(gvState()),v=clone(input),original=kind==='review'||kind==='revoke-assignment'?next.assignments.find(a=>a.id===id):kind==='revoke-direct'?next.directRules.find(a=>a.id===id):null;let userId=v.userId||original?.userId,scopeId=v.scopeId??original?.scopeId??'',on=v.starts&&v.starts>S.asOf?v.starts:S.asOf,conflicts=[];
 requireValue(gvPerson(userId)&&(scopeId===''||orgNode(scopeId)),'Choose a known person and valid location.');requireValue(!selectedScope()||gvOverlap(scopeId,selectedScope()),'The change belongs to another selected location.');giRequireAccess(scopeId);requireValue(giText(v.reason).length>=12,'Give the specific business reason before reviewing this access change.');
 if(kind==='assign'){const role=gvRole(v.roleId);requireValue(role?.status==='Active','Choose an active role.');validDate(v.starts,'Start date',false);if(v.ends){validDate(v.ends,'End date',false);requireValue(v.ends>=v.starts,'The end date must follow the start.');}requireValue(gvCovers(role.scopeRoot,scopeId,role.descendants),'The assignment exceeds this role’s maximum scope.');requireValue(!next.assignments.some(a=>a.userId===v.userId&&a.roleId===v.roleId&&a.scopeId===scopeId&&a.status==='Active'&&(!a.ends||a.ends>=v.starts)&&(!v.ends||v.ends>=a.starts)),'This person already has an overlapping assignment for this role and location.');const candidate={...v,id:'GI-PROPOSED-ASSIGNMENT',status:'Active'};conflicts=gvConflictFor(candidate);next.assignments.push(candidate);}
 else if(kind==='review'||kind==='revoke-assignment'){requireValue(original?.status==='Active','The assignment is no longer active.');if(kind==='revoke-assignment'||v.decision==='revoke'){if(original.roleId==='ROLE-ADMIN')gvKeepAdmin(original.id);original.status='Revoked';}else{requireValue(!original.ends||original.ends>=S.asOf,'This assignment expired. Use a new dated assignment to restore access.');validDate(v.reviewDue,'Next review',false);requireValue(v.reviewDue>S.asOf,'The next review must be after the workspace snapshot.');original.reviewDue=v.reviewDue;}}
 else if(kind==='direct'){requireValue(v.approvedBy===recActor().id,'The named access reviewer must act under their own working identity.');requireValue(userId!==v.approvedBy,'A recipient cannot independently approve their own direct rule.');requireValue(gvDecision(v.approvedBy,'access.manage','').allowed,'The direct-rule reviewer needs organization-wide access-management authority.');requireValue(['allow','deny'].includes(v.effect)&&GV_MODULES.some(([m])=>GV_ACTIONS.some(([a])=>m+'.'+a===v.permission)),'Choose a known permission and effect.');validDate(v.starts,'Start date',false);validDate(v.ends,'End date',false);requireValue(v.ends>=v.starts&&days(v.ends,v.starts)<=90,'Direct rules must expire within 90 days of their start date.');if(v.effect==='allow'){const [module,action]=v.permission.split('.'),opposites=action==='approve'?['edit','submit']:['edit','submit'].includes(action)?['approve']:[],covered=['',...ORG.map(n=>n.id)].filter(scope=>gvCovers(scopeId,scope)),dates=[v.starts,...next.assignments.filter(a=>a.userId===userId&&a.status==='Active'&&a.starts>=v.starts&&a.starts<=v.ends).map(a=>a.starts)];requireValue(!opposites.some(action=>covered.some(scope=>dates.some(day=>gvDecision(userId,module+'.'+action,scope,day).allowed))),'The direct grant conflicts with preparation / approval separation.');}next.directRules.push({...v,id:'GI-PROPOSED-DIRECT',status:'Active'});}
 else if(kind==='revoke-direct'){requireValue(original?.status==='Active','This rule was already revoked.');original.status='Revoked';}
 const scopes=['',...ORG.map(n=>n.id)].filter(scope=>gvCovers(scopeId,scope)),impact=giAccessComparison(next,[userId],scopes,on,kind==='direct'||kind==='revoke-direct'?[v.permission||original.permission]:undefined);
 return {kind,id,userId,scopeId,on,conflicts,impact,valuesHash:giHash(v),accessHash:giAccessHash(),reason:v.reason};}
function giWrapAccessDialog(open,kind,id=''){const context=flCaptureContext(),openedAccessHash=giAccessHash();open();const commit=modalSave;let preview=null;const button=$('#dialog button[type="submit"]');if(button)button.textContent='Review change';$('#dialog .dialog-body')?.insertAdjacentHTML('beforeend','<section id="gi-access-preview" class="gi-modal-preview" aria-live="polite"></section>');modalSave=form=>{flCheckContext(context);requireValue(giAccessHash()===openedAccessHash,'Access changed while this form was open. Reopen it to review the current assignments.');const v=values(form),next=giAccessProposal(kind,id,v);requireValue(!next.conflicts.length,'Resolve the separation-of-duties conflict. '+next.conflicts.join(' '));if(!preview||preview.valuesHash!==next.valuesHash||preview.accessHash!==next.accessHash){preview=next;const box=$('#gi-access-preview');if(box){box.innerHTML=`<h3>Review the effective access change</h3><p>${e(gvPerson(next.userId).name)} · ${e(gvScope(next.scopeId))} · evaluated ${date(next.on)}</p>${giImpactTable(next.impact)}<p class="gi-help">${kind==='review'&&v.decision!=='revoke'?'Recertification records the decision and next review date.':'The existing role assignments and explicit denies are included in this comparison.'} Apply to record this change.</p>`;box.scrollIntoView?.({block:'nearest'});}const submit=$('#dialog button[type="submit"]');if(submit)submit.textContent='Apply reviewed change';return false;}requireValue(preview.accessHash===giAccessHash(),'Access changed during review. Refresh the comparison.');const result=commit(form);save();return result;};}
