function giPolicyInput(draft,scenario='baseline'){const scope=draft.scopeId||selectedScope()||'U-IK-PAY',day=new Date(S.asOf+'T00:00:00Z').getUTCDay(),friday=addDays(S.asOf,(5-day+7)%7);return {policyId:draft.sourceId==='new'?'GI-DRAFT-POLICY':draft.sourceId,scopeId:scope,ownerId:scenario==='missing-owner'?'':recActor().id,at:(scenario==='weekend'?friday:S.asOf)+'T16:00',severity:draft.severity==='Any'?'High':draft.severity,ackAfter:scenario==='acknowledged'?'1':'',resolvedAfter:scenario==='resolved'?'1':''};}
function giPolicyValidate(d){requireValue(d&&GV_TRIGGERS.some(x=>x[0]===d.trigger),'Choose a known policy trigger.');requireValue(['calendar','business'].includes(d.clock)&&['resolved','acknowledged'].includes(d.stop),'Choose a valid response clock and stop condition.');requireValue(d.levels.length>=1&&d.levels.length<=6,'Use one to six escalation levels.');let last=-1;for(const level of d.levels){const hours=Number(level.after);requireValue(Number.isFinite(hours)&&hours>=0&&hours<=720&&hours>last,'Each delay must increase from the original trigger.');last=hours;requireValue(level.target==='owner'||gvRole(level.target)?.status==='Active','Choose an active primary role or record owner.');requireValue(gvRole(level.fallback)?.status==='Active'&&level.fallback!==level.target,'Choose a different active fallback role.');}}
