approvalRequestView=function(){const d=flRestoreApproval();if(!d)return header('Request approval','Choose the source document or published report.',link('Documents','documents','primary'));const sourceRoute=giApprovalSourceRoute(d.subject,d.snapshot.versionId),issues=giApprovalIssues(d);return header('Prepare file approval',e(d.snapshot.title)+' · '+(d.snapshot.version?'version '+d.snapshot.version:'published report snapshot'),btn('Save & return','fl-approval-save-return','','small')+btn('Discard draft','approval-cancel-draft','','quiet'),'File review')+`<div class="gi-working">${giActorControl()}<span>Requested by ${e(recUser(d.requestedBy)?.name)}. Draft routing is saved as you edit.</span></div><form id="approval-request-form" class="doc-request-layout"><section class="panel pad"><h2>People, deadline and review question</h2><div class="stack mt16">${select('template','Review stages',[['review','Review only'],['review-sign','Review, then sign off']],d.template,'data-approval-draft="template"')}${select('reviewer','Independent reviewer',giReviewPeople(d,d.reviewer),d.reviewer,'data-approval-draft="reviewer"')}${d.template==='review-sign'?select('signer','Final sign-off after review',giReviewPeople(d,d.signer,d.reviewer),d.signer,'data-approval-draft="signer"'):''}${input('due','Review deadline',d.due,'date',`data-approval-draft="due" required min="${S.asOf}"`)}${area('note','What should the reviewer decide?',d.note,'data-approval-draft="note" maxlength="1500" placeholder="State the purpose, acceptance criteria and any issue requiring challenge."')}</div><div class="gi-routing"><span>1. ${e(recUser(d.reviewer)?.name||'Choose reviewer')} reviews</span>${d.template==='review-sign'?`<span>2. ${e(recUser(d.signer)?.name||'Choose sign-off person')} signs off</span>`:''}<small>The next step opens only after the previous decision is approved.</small></div><div id="gi-approval-readiness">${giApprovalReadiness()}</div><div class="form-error" id="approval-request-error" role="alert"></div><button type="submit" id="gi-approval-send" class="btn primary" ${issues.length?'disabled':''}>Send exact version for review</button></section><section class="panel pad"><h2>Exact source being reviewed</h2><dl class="gi-facts"><div><dt>Record</dt><dd>${e(d.snapshot.title)}</dd></div><div><dt>Version</dt><dd>${d.snapshot.version?'v'+d.snapshot.version:'Captured published report'}</dd></div><div><dt>Original contributor</dt><dd>${e(recUser(d.authorId)?.name||'Not recorded')}</dd></div><div><dt>Scope</dt><dd>${d.subject.type==='document'?e(d.snapshot.scopeMode==='shared'?'Bank-wide':orgName(d.snapshot.orgScopeId)):e(recScope(d.subject.type,recRead(d.subject.type,d.subject.id)).map(orgName).join(' · ')||'Whole organization')}</dd></div></dl><div class="row wrap">${sourceRoute?link('Inspect this source',sourceRoute,'small'):''}${!approvalCurrent(d)?btn('Refresh from current source','gi-approval-refresh','','small'):''}</div><p class="gi-help">File approval records a decision about this source version. Assessment acceptance and requirement conclusions retain their own reviews.</p><details class="doc-checksum"><summary>Captured source checksum</summary><code>${e(d.snapshotHash)}</code></details></section></form>`;};
function giRefreshApproval(){const old=flRestoreApproval();requireValue(old&&old.requestedBy===recActor().id,'Switch to the original requester to refresh this draft.');const source=recRead(old.subject.type,old.subject.id);requireValue(source&&recInScope(old.subject.type,source)&&!S.scopeInvalid,'Return to the source’s original location.');const snapshot=approvalSnapshot(old.subject);if(old.vendorOnboarding){const dossier=voDossier(old.vendorOnboarding.dossierId),item=voDocumentItem(dossier,old.vendorOnboarding.itemId);requireValue(item.documentVersionId===snapshot.versionId,'Link the current source to the vendor document request before refreshing its review draft.');}const returnRoute=old.returnRoute;DOC_APPROVAL_DRAFT=null;flStoreApproval();try{approvalStart(old.subject);const draft=DOC_APPROVAL_DRAFT;Object.assign(draft,{template:old.template,reviewer:old.reviewer,signer:old.signer,due:old.due,note:old.note,returnRoute,...(old.vendorOnboarding?{vendorOnboarding:{...clone(old.vendorOnboarding),documentVersionId:snapshot.versionId}}:{})});flStoreApproval();render();toast('Draft refreshed to the current source. Review its version and routing before sending.');return draft;}catch(error){DOC_APPROVAL_DRAFT=old;flStoreApproval();throw error;}}
const giPriorApprovalSend=approvalSend;
approvalSend=async function(){const d=flRestoreApproval(),issues=giApprovalIssues(d);requireValue(!issues.length,issues.map(x=>x.message).join(' '));const before=new Set(S.governance.requests.map(r=>r.id)),origin=d?.returnRoute,hash=d?.snapshotHash,requester=d?.requestedBy;await giPriorApprovalSend();const request=S.governance.requests.find(r=>!before.has(r.id)&&r.snapshotHash===hash&&r.requestedBy===requester);if(request&&origin){request.returnRoute=origin;save();}return request;};
function giDecisionText(request,choice){const next=approvalNext(request);if(!choice)return 'Choose the decision after inspecting the exact version. Your rationale is retained with the decision receipt.';if(choice==='Request changes')return 'This request returns to the requester. Earlier decisions remain in history; a corrected source needs a new review request.';if(choice==='Reject')return 'This review closes as rejected. The source version and decision history remain available.';if(choice==='Sign off')return 'Your named sign-off completes this exact approval request. Requirement conclusions remain separate.';return request.steps.some(step=>step.order>next.order)?'This step is approved; the next named person can then complete final sign-off.':'This exact file approval completes. Assessment acceptance and requirement conclusions remain separate.';}
const giPriorApprovalView=approvalView;
approvalView=function(){const request=S.governance.requests.find(r=>r.id===current.params.get('id'));let html=giPriorApprovalView();if(!request||!approvalVisible(request))return html;const next=approvalNext(request),can=request.status==='Pending'&&next?.actorId===recActor().id&&approvalCurrent(request),sourceRoute=giApprovalSourceRoute(request.subject,request.versionId),currentRoute=giApprovalSourceRoute(request.subject),origin=request.returnRoute||sourceRoute;
 if(can){html=html.replace(/(<select name="decision"[^>]*>)([\s\S]*?)(<\/select>)/,(all,start,body,end)=>start+'<option value="" selected>Choose a decision</option>'+body.replace(/ selected/g,'')+end);html=html.replace('<p class="field-help">Recorded as',`<p class="gi-decision-effect" id="gi-decision-effect" role="status">${e(giDecisionText(request,''))}</p><p class="field-help">Recorded as`);}
 const guidance=request.status==='Pending'&&!approvalCurrent(request)?giNext({title:'This review is bound to an earlier source',description:'Inspect the current version. The requester must withdraw this pending request before preparing its replacement.',owner:recUser(request.requestedBy)?.name,primary:currentRoute?link('Inspect current source',currentRoute,'small'):''}):['Changes requested','Rejected','Cancelled'].includes(request.status)?giNext({title:request.status==='Changes requested'?'Revise the source and request another review':'Closed request retained for history',description:'Open the source to prepare a new version or review request. Previous decisions remain unchanged.',owner:recUser(request.requestedBy)?.name,primary:currentRoute?link('Open source to continue',currentRoute,'small'):''}):'';
 return html.replace('<div class="doc-record-status">',`${guidance}<div class="gi-review-links">${origin?link('Return to originating workspace',origin,'quiet small'):''}${sourceRoute&&sourceRoute!==origin?link('Open exact source version',sourceRoute,'quiet small'):''}${link('Your approval queue','approvals?tab=mine','quiet small')}</div><div class="doc-record-status">`);};
const giPriorApprovalWithdraw=actions['approval-withdraw'];actions['approval-withdraw']=el=>{const r=S.governance.requests.find(x=>x.id===el.dataset.id);requireValue(r&&approvalVisible(r),'The request is outside the current location.');const context=flCaptureContext(),state=giHash(r);giPriorApprovalWithdraw(el);const commit=modalSave;modalSave=form=>{flCheckContext(context);requireValue(r.requestedBy===recActor().id&&approvalVisible(r)&&giHash(r)===state,'The request or acting identity changed. Reopen withdrawal.');return commit(form);};};

function giSafe(fn,errorId){return (...args)=>{try{return fn(...args);}catch(error){const box=errorId&&$(errorId);if(box){box.textContent=error.message;box.hidden=false;box.scrollIntoView?.({block:'nearest'});}else toast(error.message);}};}
Object.assign(actions,{
 'gi-inbox-source':el=>giOpenNotificationSource(el.dataset.id),
 'n-open-task':el=>giOpenNotificationSource(el.dataset.id),
 'gv-save-role':giSafe(()=>{giRolePreview();go('role-change-review');},'#gv-role-error'),
 'gi-apply-role':giSafe(giApplyRole,'#gi-role-error'),
 'gv-assign-role':()=>gvAssignDialog(),
 'gv-review-assignment':el=>gvAssignmentDialog(el.dataset.id),
 'gv-revoke-assignment':el=>gvAssignmentDialog(el.dataset.id,true),
 'gv-direct-rule':()=>gvDirectDialog(),
 'gi-renew-access':el=>giRenewAccess(el.dataset.id),
 'gi-discard-open':el=>{const kind=el.dataset.kind,target=el.dataset.target;if(kind==='role'){gvState().draftRole=null;giState().rolePreview=null;delete giState().roleBases[target];}else{gvState().draftPolicy=null;giState().policyTest=null;delete giState().policyBases[target];}save();go((kind==='role'?'role-detail':'escalation-policy')+'?id='+encodeURIComponent(target));},
 'gi-policy-scenario':giSafe(el=>{giTestPolicy(giPolicyInput(gvState().draftPolicy,el.dataset.scenario),el.dataset.scenario);render();$('#gi-policy-test')?.scrollIntoView?.({block:'start'});},'#gv-policy-error'),
 'gi-focus-policy-test':()=>$('#gi-policy-test')?.scrollIntoView?.({block:'start'}),
 'gi-approval-refresh':giSafe(giRefreshApproval,'#approval-request-error')
});
document.addEventListener('submit',event=>{const form=event.target;if(form.dataset?.giFilter){event.preventDefault();const v=values(form),route=form.dataset.giFilter;if(route==='work')go(giRoute('work',{owner:v.owner,lane:v.lane,kind:v.kind,q:v.q,tab:null}));else if(route==='access-review')go(giRoute('access-review',{tab:v.tab,state:v.state,person:v.person,q:v.q}));return;}if(form.dataset?.giForm==='policy-test'){event.preventDefault();try{giTestPolicy(values(form));render();$('#gi-policy-test')?.scrollIntoView?.({block:'start'});}catch(error){const box=$('.form-error',form);if(box)box.textContent=error.message;else toast(error.message);}}});
document.addEventListener('change',event=>{const el=event.target;if(el.matches?.('[data-gi-inbox]')){const prefs=giInboxPrefs();if(el.dataset.giInbox==='sort')prefs.sort=['priority','newest'].includes(el.value)?el.value:'priority';else prefs.due=['all','overdue','soon'].includes(el.value)?el.value:'all';N_SELECTED.clear();save();nRefreshList();}if(el.matches?.('[data-approval-draft="reviewer"],[data-approval-draft="signer"]')&&DOC_APPROVAL_DRAFT){flStoreApproval();render();}if(el.closest?.('#approval-decision-form')&&el.name==='decision'){const request=S.governance.requests.find(r=>r.id===el.closest('#approval-decision-form').dataset.id),box=$('#gi-decision-effect');if(request&&box)box.textContent=giDecisionText(request,el.value);}});
document.addEventListener('input',event=>{if(!event.target.matches?.('[data-approval-draft]')||!DOC_APPROVAL_DRAFT)return;const box=$('#gi-approval-readiness'),button=$('#gi-approval-send');if(box)box.innerHTML=giApprovalReadiness();if(button)button.disabled=giApprovalIssues().length>0;});
Object.assign(titles,{'work-item':'Accountable action','role-change-review':'Review role change'});
Object.assign(window.CS_JOURNEYS,{work:giWorkView,'work-item':giWorkItemView,inbox:()=>inboxView(),notification:()=>nDetailView(),roles:()=>gvRolesView(),'role-detail':()=>gvRoleDetail(),'role-change-review':giRoleReviewView,'access-review':giAccessView,'escalation-policy':()=>gvPolicyDetail(),'approval-request':()=>approvalRequestView(),approval:()=>approvalView()});
Object.assign(window.CS_JOURNEY_GROUPS,{'work-item':'work','role-change-review':'settings'});
window.CLEAR_SIGHT_GOVERNANCE_INTERACTIONS=Object.freeze({version:'2.11',work:config=>clone(giWorkRows(config)),rolePreview:()=>clone(giRolePreview()),applyRole:giApplyRole,accessProposal:(kind,id,values)=>clone(giAccessProposal(kind,id,values)),testPolicy:values=>giTestPolicy(values),approvalIssues:()=>clone(giApprovalIssues()),openNotification:giOpenNotificationSource});
